using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ToolTechnologyChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var t=new ToolTechnologyState();var r=new ResourceState{wood=8,resin=4};Require(!t.Craft(r,0,VillageTool.BoundAxe),"Unlearned recipe crafted");for(int i=0;i<3;i++)t.Practice(0,1);Require(t.learners[0].axeKnown&&!t.learners[1].axeKnown,"Practice knowledge was global");Require(t.Craft(r,0,VillageTool.BoundAxe)&&!t.Craft(r,0,VillageTool.BoundAxe)&&r.wood==6&&r.resin==2,"Craft cost duplicated or missing");Require(t.Observe(1,0,VillageTool.BoundAxe)&&!t.Observe(1,0,VillageTool.BoundAxe)&&!t.learners[1].axeOwned&&t.learners[1].woodPractice==0,"Observation granted a free tool or fabricated practice");
  var copy=JsonUtility.FromJson<ToolTechnologyState>(JsonUtility.ToJson(t));Require(copy.Valid()&&copy.learners[1].sawAxe&&copy.learners[0].axeOwned,"Knowledge save failed");copy.resinSpent++;Require(!copy.Valid(),"Invalid technology ledger accepted");Require(new SliceState().Valid(),"Legacy season rejected");Debug.Log("BWVR_TOOLS_MODEL_PASS: personal practice, bounded recipes, costs, observation versus ownership, legacy/save validation");
 }
 [MenuItem("BWVR/Verify tool discovery and technology (Play mode)")]
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");VerifyModel();var w=UnityEngine.Object.FindAnyObjectByType<VillageResources>();var slice=w.GetComponentInParent<QuestSlice>();var f=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)f.GetValue(slice);var actors=w.Gatherers;var positions=actors.Select(a=>a.transform.position).ToArray();var rotations=actors.Select(a=>a.transform.rotation).ToArray();slice.GetComponentInChildren<CreatureHybrid>().Interrupt("Tools QA");foreach(var a in actors){a.Cancel();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();}
  var test=new SliceState{developmentFocus=true};test.Resources.wood=12;test.Resources.resin=8;test.Resources.wheat=30;f.SetValue(slice,test);w.ResetWorld();
  try{
   var maker=actors[0];for(int i=0;i<3;i++)test.Tools.Practice(0,2);maker.transform.position=w.StoreApproach;maker.GetComponent<IslandNavigator>().ResetRoute();
   actors[1].GetComponent<CarryItem>().held=true;var observer=actors[2];Require(w.Navigation.Sample(w.StoreApproach+Vector3.right*w.Navigation.Scale*6,w.Navigation.villager,2,out var watch),"No observer approach");observer.transform.position=w.Navigation.ProjectFoot(watch,w.Navigation.villager);observer.transform.rotation=Quaternion.LookRotation(w.StoreApproach-observer.transform.position);
   Require(maker.TryMakeTool()&&maker.PlannedTool==VillageTool.CultivatingHoe&&w.ReservedToolWood==2&&w.ReservedToolResin==1&&!observer.TryMakeTool(),"Native craft ownership/reservations invalid");maker.Tick(30,true);Require(test.Resources.wood==12&&!test.Tools.learners[0].hoeOwned,"Pause crafted a tool");maker.GetComponent<CarryItem>().held=true;maker.Tick(.1f,false);maker.GetComponent<CarryItem>().held=false;Require(!maker.Active&&w.ReservedToolWood==0&&test.Resources.wood==12&&!test.Tools.learners[0].hoeOwned,"Canceled craft spent material");
   Require(maker.TryMakeTool(),"Cannot retry crafting");for(int i=0;i<3000&&maker.Active;i++)maker.Tick(.05f,false);Require(test.Tools.learners[0].hoeOwned&&test.Resources.wood==10&&test.Resources.resin==7&&test.Tools.woodSpent==2,"Native hoe craft did not pay once");Require(test.Tools.learners[2].hoeKnown&&test.Tools.learners[2].sawHoe&&!test.Tools.learners[2].hoeOwned&&!test.Tools.learners[1].hoeKnown,"Nearby visible observation or held exclusion failed");actors[1].GetComponent<CarryItem>().held=false;
   var farmer=actors[1];var node=w.sources.First(s=>s.kind==VillageResource.Wheat&&!s.expansion&&w.Available(s));farmer.transform.position=node.approach;farmer.GetComponent<IslandNavigator>().ResetRoute();Require(farmer.TryBegin(node),"Cannot stage manual farm work");for(int i=0;i<1000&&farmer.Current!=VillagerResourceGathering.Phase.Carry;i++)farmer.Tick(.05f,false);Require(test.Tools.learners[1].farmPractice==0,"Undelivered harvest taught a tool");farmer.Cancel();
   for(int trip=0;trip<3;trip++){farmer.transform.position=node.approach;farmer.GetComponent<IslandNavigator>().ResetRoute();Require(farmer.TryBegin(node),"Cannot repeat useful farm work");for(int i=0;i<4000&&farmer.Active;i++)farmer.Tick(.05f,false);Require(!farmer.Active&&test.Tools.learners[1].farmPractice==trip+1,"Delivered work not credited once");}
   Require(test.Tools.learners[1].hoeKnown&&!test.Tools.learners[1].hoeOwned,"Practice failed to unlock design independently");
   // An equipped hoe really completes harvest before the former five-second time.
   maker.transform.position=node.approach;maker.GetComponent<IslandNavigator>().ResetRoute();Require(maker.TryBegin(node),"Hoe cannot harvest");maker.Tick(.05f,false);Require(maker.Current==VillagerResourceGathering.Phase.Harvest,"No harvest phase");maker.Tick(3.6f,false);Require(maker.Current==VillagerResourceGathering.Phase.Carry&&test.Resources.cargo[0].amount==3,"Hoe speed benefit did not affect native work");maker.Cancel();
   for(int i=0;i<3;i++)test.Tools.Practice(0,1);maker.transform.position=w.StoreApproach;maker.GetComponent<IslandNavigator>().ResetRoute();Require(maker.TryMakeTool(VillageTool.BoundAxe),"Cannot make learned axe");for(int i=0;i<3000&&maker.Active;i++)maker.Tick(.05f,false);
   var tree=w.sources.First(s=>s.kind==VillageResource.Wood&&!test.Resources.Find(s.id).felled&&w.Available(s));maker.transform.position=tree.approach;maker.GetComponent<IslandNavigator>().ResetRoute();Require(maker.TryBegin(tree),"Bound axe cannot begin felling");maker.Tick(.05f,false);maker.Tick(5.6f,false);Require(maker.Current==VillagerResourceGathering.Phase.Carry&&test.Resources.cargo[0].amount==3,"Bound axe speed benefit did not affect native felling");maker.Cancel();Require(test.Tools.learners[0].woodPractice==3,"Canceled wood delivery taught a lesson");
   Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Tool-equipped season does not save");Debug.Log("BWVR_TOOLS_RUNTIME_PASS: native craft/cancel/pause/costs, visible nearby learning, held exclusion, delivered-only practice, independent insight, real hoe/axe work speed and saved ownership");
  }finally{foreach(var a in actors){a.GetComponent<CarryItem>().held=false;a.Cancel();}f.SetValue(slice,original);w.ResetWorld();for(int i=0;i<actors.Length;i++){actors[i].transform.position=positions[i];actors[i].transform.rotation=rotations[i];actors[i].GetComponent<IslandNavigator>().ResetRoute();}}
 }
}
}
